CREATE TABLE test1(id INTEGER PRIMARY KEY,a); CREATE TABLE test2(id INTEGER,b); CREATE VIEW test AS SELECT test1.id AS id,a AS a,b AS b FROM test1 JOIN test2 ON test2.id=test1.id; CREATE TRIGGER I_test INSTEAD OF INSERT ON test BEGIN INSERT INTO test1(id,a) VALUES(NEW.id,NEW.a); INSERT INTO test2(id,b) VALUES(NEW.id,NEW.b); END;